export const HTML = "<img class=\"doc-banner\" alt=\"\" width=\"1200\" height=\"120\" src=\"data:image/svg+xml;base64,\">\n<h1 id=\"stage-1-review-discipline-off-the-shelf-tooling-survey\">Stage 1 — Review Discipline: Off-the-Shelf Tooling Survey</h1>\n<p>Scope: not the custom compound-review-skill pattern (already well understood — preprocessing scripts, blast-radius flagging, ticket context pulls). This covers what exists ready-made: IDE-native review features, Claude Code&#39;s own baseline, and open-source review agents worth knowing rather than rebuilding.</p>\n<p>Not about agent execution loops — for that, see <a href=\"/library/ai-tooling-crash-course-for-developers/topics/loop-engineering-agent-loops\"><code>loop-engineering-agent-loops.md</code></a>. This doc is about reviewing/verifying code output, not the &quot;run the agent again until done&quot; pattern.</p>\n<h2 id=\"1-ide-native-built-in-features\" class=\"has-num\">1. IDE-native / built-in features</h2>\n<p><strong>GitHub Copilot code review, JetBrains IDEs (including WebStorm).</strong></p>\n<figure class=\"fig\"><svg class=\"fig-wide\" viewBox=\"0 0 900 255\" role=\"img\" aria-label=\"Timeline of Copilot code review in JetBrains from September 2025 to WebStorm 2026.2, plus Cursor and JetBrains notes\"><line x1=\"60\" y1=\"64\" x2=\"840\" y2=\"64\" stroke=\"#5d5a78\" stroke-width=\"3\"/><circle cx=\"130\" cy=\"64\" r=\"11\" fill=\"#c77d00\"/><text x=\"130\" y=\"36\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#c77d00\">Sep 2025</text><text x=\"130\" y=\"100\" text-anchor=\"middle\" font-size=\"13.5\" font-weight=\"400\" fill=\"#17152a\">Copilot review ships in</text><text x=\"130\" y=\"120\" text-anchor=\"middle\" font-size=\"13.5\" font-weight=\"400\" fill=\"#17152a\">JetBrains and Visual Studio</text><circle cx=\"450\" cy=\"64\" r=\"11\" fill=\"#c77d00\"/><text x=\"450\" y=\"36\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#c77d00\">Feb 2026</text><text x=\"450\" y=\"100\" text-anchor=\"middle\" font-size=\"13.5\" font-weight=\"400\" fill=\"#17152a\">Feature updates</text><text x=\"450\" y=\"120\" text-anchor=\"middle\" font-size=\"13.5\" font-weight=\"400\" fill=\"#17152a\">to Copilot in JetBrains</text><circle cx=\"770\" cy=\"64\" r=\"11\" fill=\"#0e8c99\"/><text x=\"770\" y=\"36\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#0e8c99\">Jul 2026</text><text x=\"770\" y=\"100\" text-anchor=\"middle\" font-size=\"13.5\" font-weight=\"400\" fill=\"#17152a\">WebStorm 2026.2: Copilot</text><text x=\"770\" y=\"120\" text-anchor=\"middle\" font-size=\"13.5\" font-weight=\"400\" fill=\"#17152a\">native, no separate plugin</text><rect x=\"10\" y=\"148\" width=\"430\" height=\"92\" rx=\"14\" fill=\"#ebe6ff\" stroke=\"#6d45e0\" stroke-width=\"2\"/><text x=\"26\" y=\"178\" text-anchor=\"start\" font-size=\"15\" font-weight=\"700\" fill=\"#6d45e0\">Cursor</text><text x=\"26\" y=\"201\" text-anchor=\"start\" font-size=\"13.5\" font-weight=\"400\" fill=\"#17152a\">No distinct review feature found</text><text x=\"26\" y=\"224\" text-anchor=\"start\" font-size=\"13.5\" font-weight=\"400\" fill=\"#17152a\">AI Code Tracking API is audit, not review</text><rect x=\"460\" y=\"148\" width=\"430\" height=\"92\" rx=\"14\" fill=\"#e0f6f8\" stroke=\"#0e8c99\" stroke-width=\"2\"/><text x=\"476\" y=\"178\" text-anchor=\"start\" font-size=\"15\" font-weight=\"700\" fill=\"#0e8c99\">JetBrains own review tooling</text><text x=\"476\" y=\"201\" text-anchor=\"start\" font-size=\"13.5\" font-weight=\"400\" fill=\"#17152a\">Nothing distinct from Copilot found</text><text x=\"476\" y=\"224\" text-anchor=\"start\" font-size=\"13.5\" font-weight=\"400\" fill=\"#17152a\">AI investment routes through Copilot</text></svg><svg class=\"fig-narrow\" viewBox=\"0 0 390 363\" role=\"img\" aria-label=\"Timeline of Copilot code review in JetBrains from September 2025 to WebStorm 2026.2, plus Cursor and JetBrains notes\"><line x1=\"30\" y1=\"22\" x2=\"30\" y2=\"137\" stroke=\"#5d5a78\" stroke-width=\"3\"/><circle cx=\"30\" cy=\"22\" r=\"9\" fill=\"#c77d00\"/><text x=\"54\" y=\"27\" text-anchor=\"start\" font-size=\"14\" font-weight=\"700\" fill=\"#c77d00\">Sep 2025</text><text x=\"54\" y=\"46\" text-anchor=\"start\" font-size=\"13\" font-weight=\"400\" fill=\"#17152a\">Copilot review ships in JetBrains and</text><text x=\"54\" y=\"63\" text-anchor=\"start\" font-size=\"13\" font-weight=\"400\" fill=\"#17152a\">Visual Studio</text><circle cx=\"30\" cy=\"88\" r=\"9\" fill=\"#c77d00\"/><text x=\"54\" y=\"93\" text-anchor=\"start\" font-size=\"14\" font-weight=\"700\" fill=\"#c77d00\">Feb 2026</text><text x=\"54\" y=\"112\" text-anchor=\"start\" font-size=\"13\" font-weight=\"400\" fill=\"#17152a\">Feature updates to Copilot in JetBrains</text><circle cx=\"30\" cy=\"137\" r=\"9\" fill=\"#0e8c99\"/><text x=\"54\" y=\"142\" text-anchor=\"start\" font-size=\"14\" font-weight=\"700\" fill=\"#0e8c99\">Jul 2026</text><text x=\"54\" y=\"161\" text-anchor=\"start\" font-size=\"13\" font-weight=\"400\" fill=\"#17152a\">WebStorm 2026.2: Copilot native, no</text><text x=\"54\" y=\"178\" text-anchor=\"start\" font-size=\"13\" font-weight=\"400\" fill=\"#17152a\">separate plugin</text><rect x=\"10\" y=\"201\" width=\"370\" height=\"71\" rx=\"12\" fill=\"#ebe6ff\" stroke=\"#6d45e0\" stroke-width=\"2\"/><text x=\"195\" y=\"224\" text-anchor=\"middle\" font-size=\"15\" font-weight=\"700\" fill=\"#6d45e0\">Cursor</text><text x=\"195\" y=\"244\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"400\" fill=\"#17152a\">No distinct review feature found</text><text x=\"195\" y=\"261\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"400\" fill=\"#17152a\">AI Code Tracking API is audit, not review</text><rect x=\"10\" y=\"282\" width=\"370\" height=\"71\" rx=\"12\" fill=\"#e0f6f8\" stroke=\"#0e8c99\" stroke-width=\"2\"/><text x=\"195\" y=\"305\" text-anchor=\"middle\" font-size=\"15\" font-weight=\"700\" fill=\"#0e8c99\">JetBrains own review tooling</text><text x=\"195\" y=\"325\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"400\" fill=\"#17152a\">Nothing distinct from Copilot found</text><text x=\"195\" y=\"342\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"400\" fill=\"#17152a\">AI investment routes through Copilot</text></svg><figcaption>Copilot is a single-pass first catch. Cursor folds review into the agent loop.</figcaption></figure>\n\n<figure class=\"fig\"><svg class=\"fig-wide\" viewBox=\"0 0 900 228\" role=\"img\" aria-label=\"Review tools placed on a spectrum from single-pass to fresh-context to different-model\"><line x1=\"40\" y1=\"110\" x2=\"860\" y2=\"110\" stroke=\"#5d5a78\" stroke-width=\"3\"/><path d=\"M840 110L853.0 110.0\" stroke=\"#5d5a78\" stroke-width=\"3\" fill=\"none\"/><path d=\"M862 110L853.0 116.0L853.0 104.0z\" fill=\"#5d5a78\"/><text x=\"40\" y=\"28\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"#5d5a78\">how independent is the reviewer?</text><circle cx=\"70\" cy=\"110\" r=\"10\" fill=\"#c77d00\"/><text x=\"70\" y=\"50\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#c77d00\">Copilot code review</text><text x=\"70\" y=\"70\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"400\" fill=\"#17152a\">single pass</text><circle cx=\"250\" cy=\"110\" r=\"10\" fill=\"#0e8c99\"/><text x=\"250\" y=\"150\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#0e8c99\">PR-Agent, CodeRabbit</text><text x=\"250\" y=\"170\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"400\" fill=\"#17152a\">automated PR review</text><circle cx=\"470\" cy=\"110\" r=\"10\" fill=\"#6d45e0\"/><text x=\"470\" y=\"50\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#6d45e0\">Claude Code</text><text x=\"470\" y=\"70\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"400\" fill=\"#17152a\">code-reviewer subagent: fresh context</text><circle cx=\"700\" cy=\"110\" r=\"10\" fill=\"#c21c7a\"/><text x=\"700\" y=\"150\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#c21c7a\">second-opinion plugin</text><text x=\"700\" y=\"170\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"400\" fill=\"#17152a\">other model family (unproven, 0 stars)</text><text x=\"450\" y=\"214\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"400\" fill=\"#5d5a78\">a first-pass catch is not a cold-start critic. Check whether your tool does it before rebuilding it.</text></svg><svg class=\"fig-narrow\" viewBox=\"0 0 390 292\" role=\"img\" aria-label=\"Review tools placed on a spectrum from single-pass to fresh-context to different-model\"><text x=\"10\" y=\"24\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"#5d5a78\">how independent is the reviewer?</text><line x1=\"30\" y1=\"47\" x2=\"30\" y2=\"194\" stroke=\"#5d5a78\" stroke-width=\"3\"/><circle cx=\"30\" cy=\"47\" r=\"9\" fill=\"#c77d00\"/><text x=\"54\" y=\"52\" text-anchor=\"start\" font-size=\"14\" font-weight=\"700\" fill=\"#c77d00\">Copilot code review</text><text x=\"54\" y=\"71\" text-anchor=\"start\" font-size=\"13\" font-weight=\"400\" fill=\"#17152a\">single pass</text><circle cx=\"30\" cy=\"96\" r=\"9\" fill=\"#0e8c99\"/><text x=\"54\" y=\"101\" text-anchor=\"start\" font-size=\"14\" font-weight=\"700\" fill=\"#0e8c99\">PR-Agent, CodeRabbit</text><text x=\"54\" y=\"120\" text-anchor=\"start\" font-size=\"13\" font-weight=\"400\" fill=\"#17152a\">automated PR review</text><circle cx=\"30\" cy=\"145\" r=\"9\" fill=\"#6d45e0\"/><text x=\"54\" y=\"150\" text-anchor=\"start\" font-size=\"14\" font-weight=\"700\" fill=\"#6d45e0\">Claude Code</text><text x=\"54\" y=\"169\" text-anchor=\"start\" font-size=\"13\" font-weight=\"400\" fill=\"#17152a\">code-reviewer subagent: fresh context</text><circle cx=\"30\" cy=\"194\" r=\"9\" fill=\"#c21c7a\"/><text x=\"54\" y=\"199\" text-anchor=\"start\" font-size=\"14\" font-weight=\"700\" fill=\"#c21c7a\">second-opinion plugin</text><text x=\"54\" y=\"218\" text-anchor=\"start\" font-size=\"13\" font-weight=\"400\" fill=\"#17152a\">other model family (unproven, 0 stars)</text><text x=\"195\" y=\"249\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"400\" fill=\"#5d5a78\">a first-pass catch is not a cold-start critic.</text><text x=\"195\" y=\"266\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"400\" fill=\"#5d5a78\">Check whether your tool does it before</text><text x=\"195\" y=\"283\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"400\" fill=\"#5d5a78\">rebuilding it.</text></svg><figcaption>Where common review tools sit on independence.</figcaption></figure>\n\n<ul>\n<li>Shipped to JetBrains and Visual Studio in September 2025, feature updates through Feb 2026 (<a href=\"https://github.blog/changelog/2025-09-18-copilot-code-review-now-in-jetbrains-ides-and-visual-studio/\">Sep 2025 changelog</a>, <a href=\"https://github.blog/changelog/2026-02-13-new-features-and-improvements-in-github-copilot-in-jetbrains-ides-2/\">Feb 2026 changelog</a>).</li>\n<li>Invoke from the PR context menu (Copilot → Request a Review) to self-review before opening a PR. Feedback lands inline: logic, security, performance issues.</li>\n<li>WebStorm 2026.2 onward: Copilot is natively integrated, no separate plugin (<a href=\"https://blog.jetbrains.com/webstorm/2026/07/webstorm-2026-2/\">JetBrains blog, Jul 2026</a>). Agent Skills support is in preview inside the JetBrains Copilot plugin.</li>\n<li>Versus cold-start-critic: single-pass reviewer, not confirmed to run with a fresh isolated context. Sourcing describes what it flags, not its isolation guarantees. Treat as a useful first-pass catch, not a substitute for a real fresh-context critic.</li>\n</ul>\n<p><strong>Cursor.</strong> No distinct review feature comparable to Copilot&#39;s. 2026 coverage centers on agent/autonomous-loop capabilities instead — Background Agents on separate branches opening PRs, Cloud Agents running in parallel. Enterprise plan has an &quot;AI Code Tracking API&quot; (attribution/audit logging of which model wrote which line) — an audit tool, not a review tool. If self-review happens, it&#39;s folded into the agent loop, not a separate reviewer role. Sourcing here is thinner than for Copilot.</p>\n<p><strong>JetBrains&#39; own AI review tooling independent of Copilot</strong> — nothing distinct turned up; JetBrains&#39; 2026 AI investment in WebStorm appears to route through the Copilot integration rather than a separate native reviewer.</p>\n<h2 id=\"2-claude-codes-own-baseline-this-sessions-harness\" class=\"has-num\">2. Claude Code&#39;s own baseline (this session&#39;s harness)</h2>\n<p>The most-documented fresh-context-critic implementation available, per <a href=\"https://code.claude.com/docs/en/code-review\">Claude Code docs</a>:</p>\n<figure class=\"fig\"><svg class=\"fig-wide\" viewBox=\"0 0 900 225\" role=\"img\" aria-label=\"Three Claude Code review surfaces and the two 2026 launch dates\"><rect x=\"10\" y=\"10\" width=\"280\" height=\"100\" rx=\"14\" fill=\"#ebe6ff\" stroke=\"#6d45e0\" stroke-width=\"2\"/><text x=\"26\" y=\"40\" text-anchor=\"start\" font-size=\"15\" font-weight=\"700\" fill=\"#6d45e0\">/code-review</text><text x=\"26\" y=\"63\" text-anchor=\"start\" font-size=\"13.5\" font-weight=\"400\" fill=\"#17152a\">Reviews a local diff</text><rect x=\"310\" y=\"10\" width=\"280\" height=\"100\" rx=\"14\" fill=\"#e0f6f8\" stroke=\"#0e8c99\" stroke-width=\"2\"/><text x=\"326\" y=\"40\" text-anchor=\"start\" font-size=\"15\" font-weight=\"700\" fill=\"#0e8c99\">Code Review on PRs</text><text x=\"326\" y=\"63\" text-anchor=\"start\" font-size=\"13.5\" font-weight=\"400\" fill=\"#17152a\">Team and Enterprise plans</text><text x=\"326\" y=\"86\" text-anchor=\"start\" font-size=\"13.5\" font-weight=\"400\" fill=\"#17152a\">Fleet of specialized agents</text><rect x=\"610\" y=\"10\" width=\"280\" height=\"100\" rx=\"14\" fill=\"#dff5ea\" stroke=\"#12915a\" stroke-width=\"2\"/><text x=\"626\" y=\"40\" text-anchor=\"start\" font-size=\"15\" font-weight=\"700\" fill=\"#12915a\">code-reviewer subagent</text><text x=\"626\" y=\"63\" text-anchor=\"start\" font-size=\"13.5\" font-weight=\"400\" fill=\"#17152a\">Own system prompt</text><text x=\"626\" y=\"86\" text-anchor=\"start\" font-size=\"13.5\" font-weight=\"400\" fill=\"#17152a\">Fresh context, cold start</text><line x1=\"60\" y1=\"170\" x2=\"840\" y2=\"170\" stroke=\"#5d5a78\" stroke-width=\"3\"/><circle cx=\"250\" cy=\"170\" r=\"11\" fill=\"#6d45e0\"/><text x=\"250\" y=\"142\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#6d45e0\">Mar 2026</text><text x=\"250\" y=\"208\" text-anchor=\"middle\" font-size=\"13.5\" font-weight=\"400\" fill=\"#17152a\">Official Code Review ships</text><circle cx=\"650\" cy=\"170\" r=\"11\" fill=\"#0e8c99\"/><text x=\"650\" y=\"142\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#0e8c99\">Apr 2026</text><text x=\"650\" y=\"208\" text-anchor=\"middle\" font-size=\"13.5\" font-weight=\"400\" fill=\"#17152a\">/ultrareview: cloud multi-agent bug hunter</text></svg><svg class=\"fig-narrow\" viewBox=\"0 0 390 342\" role=\"img\" aria-label=\"Three Claude Code review surfaces and the two 2026 launch dates\"><rect x=\"10\" y=\"10\" width=\"370\" height=\"54\" rx=\"12\" fill=\"#ebe6ff\" stroke=\"#6d45e0\" stroke-width=\"2\"/><text x=\"195\" y=\"33\" text-anchor=\"middle\" font-size=\"15\" font-weight=\"700\" fill=\"#6d45e0\">/code-review</text><text x=\"195\" y=\"53\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"400\" fill=\"#17152a\">Reviews a local diff</text><rect x=\"10\" y=\"74\" width=\"370\" height=\"71\" rx=\"12\" fill=\"#e0f6f8\" stroke=\"#0e8c99\" stroke-width=\"2\"/><text x=\"195\" y=\"97\" text-anchor=\"middle\" font-size=\"15\" font-weight=\"700\" fill=\"#0e8c99\">Code Review on PRs</text><text x=\"195\" y=\"117\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"400\" fill=\"#17152a\">Team and Enterprise plans</text><text x=\"195\" y=\"134\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"400\" fill=\"#17152a\">Fleet of specialized agents</text><rect x=\"10\" y=\"155\" width=\"370\" height=\"71\" rx=\"12\" fill=\"#dff5ea\" stroke=\"#12915a\" stroke-width=\"2\"/><text x=\"195\" y=\"178\" text-anchor=\"middle\" font-size=\"15\" font-weight=\"700\" fill=\"#12915a\">code-reviewer subagent</text><text x=\"195\" y=\"198\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"400\" fill=\"#17152a\">Own system prompt</text><text x=\"195\" y=\"215\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"400\" fill=\"#17152a\">Fresh context, cold start</text><line x1=\"30\" y1=\"252\" x2=\"30\" y2=\"301\" stroke=\"#5d5a78\" stroke-width=\"3\"/><circle cx=\"30\" cy=\"252\" r=\"9\" fill=\"#6d45e0\"/><text x=\"54\" y=\"257\" text-anchor=\"start\" font-size=\"14\" font-weight=\"700\" fill=\"#6d45e0\">Mar 2026</text><text x=\"54\" y=\"276\" text-anchor=\"start\" font-size=\"13\" font-weight=\"400\" fill=\"#17152a\">Official Code Review ships</text><circle cx=\"30\" cy=\"301\" r=\"9\" fill=\"#0e8c99\"/><text x=\"54\" y=\"306\" text-anchor=\"start\" font-size=\"14\" font-weight=\"700\" fill=\"#0e8c99\">Apr 2026</text><text x=\"54\" y=\"325\" text-anchor=\"start\" font-size=\"13\" font-weight=\"400\" fill=\"#17152a\">/ultrareview: cloud multi-agent bug hunter</text></svg><figcaption>The cold-start critic is productized here, so check before rebuilding it.</figcaption></figure>\n\n<ul>\n<li><code>/code-review</code> reviews a local diff.</li>\n<li>Team/Enterprise: &quot;Code Review&quot; runs on GitHub PRs directly, posting inline comments from &quot;a fleet of specialized agents&quot; checking changes against the full codebase — logic errors, security issues, broken edge cases, regressions.</li>\n<li>The <code>code-reviewer</code> subagent type runs with its own focused system prompt and fresh context — built around the cold-start pattern, not self-review.</li>\n<li>Official Code Review shipped March 2026; <code>/ultrareview</code> (cloud-based multi-agent bug hunter) shipped April 2026.</li>\n</ul>\n<p>Confirms the cold-start-critic pattern is productized here, not just a DIY technique — check for it elsewhere before rebuilding it.</p>\n<h2 id=\"3-open-source-review-agents\" class=\"has-num\">3. Open-source review agents</h2>\n<p><strong>PR-Agent (qodo-ai/pr-agent, formerly Codium-PR-Agent).</strong> The clear leader by adoption: ~10.7k GitHub stars, ~1.4k forks, active maintenance. Self-hostable as a GitHub Action, provider-agnostic (Anthropic, OpenAI, Google, others behind a unified interface), triggered via slash commands (<code>/review</code>, <code>/describe</code>, <code>/improve</code>, <code>/ask</code>) on GitHub, GitLab, Bitbucket, or Azure DevOps. This is the one genuinely worth trying for a single-developer setup — real repo health, self-hostable, not locked to one model vendor, which fits the provider-independence constraint.</p>\n<figure class=\"fig\"><svg class=\"fig-wide\" viewBox=\"0 0 900 225\" role=\"img\" aria-label=\"PR-Agent adoption and commands compared with the commercial CodeRabbit and Sourcery\"><rect x=\"10\" y=\"10\" width=\"520\" height=\"200\" rx=\"14\" fill=\"#e0f6f8\" stroke=\"#0e8c99\" stroke-width=\"2\"/><text x=\"26\" y=\"38\" text-anchor=\"start\" font-size=\"15\" font-weight=\"700\" fill=\"#0e8c99\">PR-Agent (qodo-ai/pr-agent)</text><text x=\"26\" y=\"76\" text-anchor=\"start\" font-size=\"24\" font-weight=\"700\" fill=\"#0e8c99\">~10.7k stars</text><text x=\"280\" y=\"76\" text-anchor=\"start\" font-size=\"24\" font-weight=\"700\" fill=\"#0e8c99\">~1.4k forks</text><rect x=\"26\" y=\"96\" width=\"110\" height=\"34\" rx=\"17\" fill=\"#0e8c99\" stroke=\"#0e8c99\" stroke-width=\"2\"/><text x=\"81\" y=\"118\" text-anchor=\"middle\" font-size=\"13.5\" font-weight=\"700\" fill=\"#fff\">/review</text><rect x=\"148\" y=\"96\" width=\"110\" height=\"34\" rx=\"17\" fill=\"#0e8c99\" stroke=\"#0e8c99\" stroke-width=\"2\"/><text x=\"203\" y=\"118\" text-anchor=\"middle\" font-size=\"13.5\" font-weight=\"700\" fill=\"#fff\">/describe</text><rect x=\"270\" y=\"96\" width=\"110\" height=\"34\" rx=\"17\" fill=\"#0e8c99\" stroke=\"#0e8c99\" stroke-width=\"2\"/><text x=\"325\" y=\"118\" text-anchor=\"middle\" font-size=\"13.5\" font-weight=\"700\" fill=\"#fff\">/improve</text><rect x=\"392\" y=\"96\" width=\"110\" height=\"34\" rx=\"17\" fill=\"#0e8c99\" stroke=\"#0e8c99\" stroke-width=\"2\"/><text x=\"447\" y=\"118\" text-anchor=\"middle\" font-size=\"13.5\" font-weight=\"700\" fill=\"#fff\">/ask</text><text x=\"26\" y=\"158\" text-anchor=\"start\" font-size=\"14\" font-weight=\"400\" fill=\"#17152a\">GitHub, GitLab, Bitbucket, Azure DevOps</text><text x=\"26\" y=\"182\" text-anchor=\"start\" font-size=\"13.5\" font-weight=\"400\" fill=\"#17152a\">Self-hostable Action, Anthropic, OpenAI, Google and more</text><rect x=\"550\" y=\"10\" width=\"340\" height=\"92\" rx=\"14\" fill=\"#fff1d6\" stroke=\"#c77d00\" stroke-width=\"2\"/><text x=\"566\" y=\"40\" text-anchor=\"start\" font-size=\"15\" font-weight=\"700\" fill=\"#c77d00\">CodeRabbit</text><text x=\"566\" y=\"63\" text-anchor=\"start\" font-size=\"13.5\" font-weight=\"400\" fill=\"#17152a\">Commercial SaaS, not open source</text><text x=\"566\" y=\"86\" text-anchor=\"start\" font-size=\"13.5\" font-weight=\"400\" fill=\"#17152a\">Free tier covers private repos</text><rect x=\"550\" y=\"118\" width=\"340\" height=\"92\" rx=\"14\" fill=\"#fff1d6\" stroke=\"#c77d00\" stroke-width=\"2\"/><text x=\"566\" y=\"148\" text-anchor=\"start\" font-size=\"15\" font-weight=\"700\" fill=\"#c77d00\">Sourcery</text><text x=\"566\" y=\"171\" text-anchor=\"start\" font-size=\"13.5\" font-weight=\"400\" fill=\"#17152a\">Commercial SaaS, Python-refactor lean</text><text x=\"566\" y=\"194\" text-anchor=\"start\" font-size=\"13.5\" font-weight=\"400\" fill=\"#17152a\">Free tier: open-source projects only</text></svg><svg class=\"fig-narrow\" viewBox=\"0 0 390 374\" role=\"img\" aria-label=\"PR-Agent adoption and commands compared with the commercial CodeRabbit and Sourcery\"><rect x=\"10\" y=\"10\" width=\"370\" height=\"192\" rx=\"12\" fill=\"#e0f6f8\" stroke=\"#0e8c99\" stroke-width=\"2\"/><text x=\"195\" y=\"36\" text-anchor=\"middle\" font-size=\"15\" font-weight=\"700\" fill=\"#0e8c99\">PR-Agent (qodo-ai/pr-agent)</text><text x=\"22\" y=\"72\" text-anchor=\"start\" font-size=\"22\" font-weight=\"700\" fill=\"#0e8c99\">~10.7k stars</text><text x=\"205\" y=\"72\" text-anchor=\"start\" font-size=\"22\" font-weight=\"700\" fill=\"#0e8c99\">~1.4k forks</text><rect x=\"22\" y=\"88\" width=\"80\" height=\"30\" rx=\"15\" fill=\"#0e8c99\"/><text x=\"62\" y=\"108\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"700\" fill=\"#fff\">/review</text><rect x=\"107\" y=\"88\" width=\"80\" height=\"30\" rx=\"15\" fill=\"#0e8c99\"/><text x=\"147\" y=\"108\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"700\" fill=\"#fff\">/describe</text><rect x=\"192\" y=\"88\" width=\"80\" height=\"30\" rx=\"15\" fill=\"#0e8c99\"/><text x=\"232\" y=\"108\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"700\" fill=\"#fff\">/improve</text><rect x=\"277\" y=\"88\" width=\"80\" height=\"30\" rx=\"15\" fill=\"#0e8c99\"/><text x=\"317\" y=\"108\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"700\" fill=\"#fff\">/ask</text><text x=\"195\" y=\"144\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"400\" fill=\"#17152a\">GitHub, GitLab, Bitbucket, Azure DevOps</text><text x=\"195\" y=\"162\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"400\" fill=\"#17152a\">Self-hostable Action, Anthropic, OpenAI,</text><text x=\"195\" y=\"180\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"400\" fill=\"#17152a\">Google and more</text><rect x=\"10\" y=\"212\" width=\"370\" height=\"71\" rx=\"12\" fill=\"#fff1d6\" stroke=\"#c77d00\" stroke-width=\"2\"/><text x=\"195\" y=\"235\" text-anchor=\"middle\" font-size=\"15\" font-weight=\"700\" fill=\"#c77d00\">CodeRabbit</text><text x=\"195\" y=\"255\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"400\" fill=\"#17152a\">Commercial SaaS, not open source</text><text x=\"195\" y=\"272\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"400\" fill=\"#17152a\">Free tier covers private repos</text><rect x=\"10\" y=\"293\" width=\"370\" height=\"71\" rx=\"12\" fill=\"#fff1d6\" stroke=\"#c77d00\" stroke-width=\"2\"/><text x=\"195\" y=\"316\" text-anchor=\"middle\" font-size=\"15\" font-weight=\"700\" fill=\"#c77d00\">Sourcery</text><text x=\"195\" y=\"336\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"400\" fill=\"#17152a\">Commercial SaaS, Python-refactor lean</text><text x=\"195\" y=\"353\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"400\" fill=\"#17152a\">Free tier: open-source projects only</text></svg><figcaption>The one worth trying solo: self-hostable and not tied to one model vendor.</figcaption></figure>\n\n<p><strong>CodeRabbit / Sourcery</strong> — both commercial SaaS, not self-hosted open-source. CodeRabbit has a free tier covering private repos; Sourcery&#39;s free tier is limited to open-source projects and is more Python-refactoring-focused. Neither is open-source in the way PR-Agent is; noted for completeness, not recommended over PR-Agent for this use case.</p>\n<h2 id=\"4-reusable-second-opinion-cold-start-critic-implementations\" class=\"has-num\">4. Reusable &quot;second opinion&quot; / cold-start-critic implementations</h2>\n<p>One direct hit: <strong><code>pghqdev/second-opinion</code></strong> — a Claude Code plugin/skill that intercepts risky plans (migrations, auth changes, production deploys, destructive ops) via a <code>PreToolUse</code> hook, routes them to a different-lineage model (Codex, Gemini, Opencode) for adversarial review, returns <code>SHIP</code> / <code>REVISE</code> / <code>RECONSIDER</code>. Exactly the cross-provider cold-start pattern the user&#39;s own review-discipline principle calls for.</p>\n<figure class=\"fig\"><svg class=\"fig-wide\" viewBox=\"0 0 900 232\" role=\"img\" aria-label=\"A writer hands a diff and real command output to a fresh-context critic that returns a typed verdict\"><rect x=\"10\" y=\"70\" width=\"160\" height=\"70\" rx=\"12\" fill=\"#ebe6ff\" stroke=\"#6d45e0\" stroke-width=\"2\"/><text x=\"90.0\" y=\"100.2\" text-anchor=\"middle\" font-size=\"15\" font-weight=\"700\" fill=\"#17152a\">Writer agent</text><text x=\"90.0\" y=\"120.2\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"400\" fill=\"#17152a\">wrote the code</text><rect x=\"230\" y=\"70\" width=\"200\" height=\"70\" rx=\"12\" fill=\"#fff1d6\" stroke=\"#c77d00\" stroke-width=\"2\"/><text x=\"330.0\" y=\"100.2\" text-anchor=\"middle\" font-size=\"15\" font-weight=\"700\" fill=\"#17152a\">Diff + pasted</text><text x=\"330.0\" y=\"120.2\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"400\" fill=\"#17152a\">command output</text><rect x=\"490\" y=\"70\" width=\"210\" height=\"70\" rx=\"12\" fill=\"#0e8c99\" stroke=\"#0e8c99\" stroke-width=\"2\"/><text x=\"595.0\" y=\"100.2\" text-anchor=\"middle\" font-size=\"15\" font-weight=\"700\" fill=\"#fff\">Critic agent</text><text x=\"595.0\" y=\"120.2\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"400\" fill=\"#fff\">fresh context, other model</text><rect x=\"760\" y=\"70\" width=\"130\" height=\"70\" rx=\"12\" fill=\"#12915a\" stroke=\"#12915a\" stroke-width=\"2\"/><text x=\"825.0\" y=\"100.2\" text-anchor=\"middle\" font-size=\"15\" font-weight=\"700\" fill=\"#fff\">Typed verdict</text><text x=\"825.0\" y=\"120.2\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"400\" fill=\"#fff\">PASS / FAIL</text><path d=\"M172 105L219.0 105.0\" stroke=\"#5d5a78\" stroke-width=\"3\" fill=\"none\"/><path d=\"M228 105L219.0 111.0L219.0 99.0z\" fill=\"#5d5a78\"/><path d=\"M432 105L479.0 105.0\" stroke=\"#5d5a78\" stroke-width=\"3\" fill=\"none\"/><path d=\"M488 105L479.0 111.0L479.0 99.0z\" fill=\"#5d5a78\"/><path d=\"M702 105L749.0 105.0\" stroke=\"#5d5a78\" stroke-width=\"3\" fill=\"none\"/><path d=\"M758 105L749.0 111.0L749.0 99.0z\" fill=\"#5d5a78\"/><rect x=\"10\" y=\"170\" width=\"330\" height=\"44\" rx=\"12\" fill=\"#ffe6f3\" stroke=\"#c21c7a\" stroke-width=\"2\" stroke-dasharray=\"7 6\"/><text x=\"175.0\" y=\"196.9\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#17152a\">✕  same context grades its own homework</text><rect x=\"380\" y=\"170\" width=\"350\" height=\"44\" rx=\"12\" fill=\"#ffe6f3\" stroke=\"#c21c7a\" stroke-width=\"2\" stroke-dasharray=\"7 6\"/><text x=\"555.0\" y=\"196.9\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#17152a\">✕  3 agents voting: correlated errors</text><text x=\"450\" y=\"24\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#5d5a78\">evidence over claims</text></svg><svg class=\"fig-narrow\" viewBox=\"0 0 390 397\" role=\"img\" aria-label=\"A writer hands a diff and real command output to a fresh-context critic that returns a typed verdict\"><text x=\"195\" y=\"24\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#5d5a78\">evidence over claims</text><rect x=\"10\" y=\"35\" width=\"370\" height=\"54\" rx=\"12\" fill=\"#ebe6ff\" stroke=\"#6d45e0\" stroke-width=\"2\"/><text x=\"195\" y=\"58\" text-anchor=\"middle\" font-size=\"15\" font-weight=\"700\" fill=\"#6d45e0\">Writer agent</text><text x=\"195\" y=\"78\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"400\" fill=\"#17152a\">wrote the code</text><path d=\"M195 92 L195 103\" stroke=\"#5d5a78\" stroke-width=\"3\" fill=\"none\"/><path d=\"M195 111 L189 102 L201 102 z\" fill=\"#5d5a78\"/><rect x=\"10\" y=\"111\" width=\"370\" height=\"34\" rx=\"12\" fill=\"#fff1d6\" stroke=\"#c77d00\" stroke-width=\"2\"/><text x=\"195\" y=\"134\" text-anchor=\"middle\" font-size=\"15\" font-weight=\"700\" fill=\"#c77d00\">Diff + pasted command output</text><path d=\"M195 148 L195 159\" stroke=\"#5d5a78\" stroke-width=\"3\" fill=\"none\"/><path d=\"M195 167 L189 158 L201 158 z\" fill=\"#5d5a78\"/><rect x=\"10\" y=\"167\" width=\"370\" height=\"54\" rx=\"12\" fill=\"#0e8c99\" stroke=\"#0e8c99\" stroke-width=\"2\"/><text x=\"195\" y=\"190\" text-anchor=\"middle\" font-size=\"15\" font-weight=\"700\" fill=\"#fff\">Critic agent</text><text x=\"195\" y=\"210\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"400\" fill=\"#fff\">fresh context, other model</text><path d=\"M195 224 L195 235\" stroke=\"#5d5a78\" stroke-width=\"3\" fill=\"none\"/><path d=\"M195 243 L189 234 L201 234 z\" fill=\"#5d5a78\"/><rect x=\"10\" y=\"243\" width=\"370\" height=\"54\" rx=\"12\" fill=\"#12915a\" stroke=\"#12915a\" stroke-width=\"2\"/><text x=\"195\" y=\"266\" text-anchor=\"middle\" font-size=\"15\" font-weight=\"700\" fill=\"#fff\">Typed verdict</text><text x=\"195\" y=\"286\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"400\" fill=\"#fff\">PASS / FAIL</text><rect x=\"10\" y=\"311\" width=\"370\" height=\"34\" rx=\"12\" fill=\"#ffe6f3\" stroke=\"#c21c7a\" stroke-width=\"2\" stroke-dasharray=\"7 6\"/><text x=\"195\" y=\"333\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"400\" fill=\"#17152a\">✕ same context grades its own homework</text><rect x=\"10\" y=\"353\" width=\"370\" height=\"34\" rx=\"12\" fill=\"#ffe6f3\" stroke=\"#c21c7a\" stroke-width=\"2\" stroke-dasharray=\"7 6\"/><text x=\"195\" y=\"375\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"400\" fill=\"#17152a\">✕ 3 agents voting: correlated errors</text></svg><figcaption>Cold-start critic, ideally another model family, forced into a verdict with evidence.</figcaption></figure>\n\n<p><strong>Flagged, not recommended as-is:</strong> 0 stars, 0 forks, 6 commits — a solo, unproven prototype. Worth reading as a working example (install script, hook mechanism, fallback-to-self-review when no external reviewer is configured), not worth adopting sight-unseen. If the pattern is wanted, building a small version directly may be more solid than depending on this unmaintained one-person repo.</p>\n<p>No other standalone reusable cold-start-critic tool turned up. The pattern mostly lives as <em>guidance</em> (Anthropic&#39;s best-practices docs, Augment Code&#39;s &quot;adversarial code review&quot; writeups) rather than a mature ecosystem of ready tools. <code>pghqdev/second-opinion</code> is the only concrete implementation found, and it&#39;s early.</p>\n<h2 id=\"what-this-leaves-open\">What this leaves open</h2>\n<p>The gap between &quot;IDE gives you a review button&quot; and &quot;a fresh, different-lineage critic reviews this&quot; is still mostly closed by DIY — either Claude Code&#39;s built-in subagent pattern (solid, documented, in-house) or a self-built cross-provider hook similar to <code>second-opinion</code>&#39;s approach. PR-Agent is the one mature, self-hostable, provider-agnostic option worth trying for day-to-day PR review; nothing else in the open-source space matched it on repo health.</p>\n<figure class=\"fig\"><svg class=\"fig-wide\" viewBox=\"0 0 900 222\" role=\"img\" aria-label=\"Which tool closes which review gap: PR-Agent, the Claude Code subagent, or a self-built cross-provider hook\"><rect x=\"10\" y=\"10\" width=\"280\" height=\"60\" rx=\"14\" fill=\"#e0f6f8\" stroke=\"#0e8c99\" stroke-width=\"2\"/><text x=\"150\" y=\"46\" text-anchor=\"middle\" font-size=\"15\" font-weight=\"700\" fill=\"#17152a\">Day-to-day PR review</text><path d=\"M150 74L150 99\" stroke=\"#5d5a78\" stroke-width=\"3\" fill=\"none\"/><path d=\"M150 108L144 99L156 99z\" fill=\"#5d5a78\"/><rect x=\"10\" y=\"114\" width=\"280\" height=\"92\" rx=\"14\" fill=\"#e0f6f8\" stroke=\"#0e8c99\" stroke-width=\"2\"/><text x=\"150\" y=\"148\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#0e8c99\">PR-Agent</text><text x=\"150\" y=\"176\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"400\" fill=\"#17152a\">mature, self-hostable, provider-agnostic</text><rect x=\"310\" y=\"10\" width=\"280\" height=\"60\" rx=\"14\" fill=\"#ebe6ff\" stroke=\"#6d45e0\" stroke-width=\"2\"/><text x=\"450\" y=\"46\" text-anchor=\"middle\" font-size=\"15\" font-weight=\"700\" fill=\"#17152a\">Fresh-context critic</text><path d=\"M450 74L450 99\" stroke=\"#5d5a78\" stroke-width=\"3\" fill=\"none\"/><path d=\"M450 108L444 99L456 99z\" fill=\"#5d5a78\"/><rect x=\"310\" y=\"114\" width=\"280\" height=\"92\" rx=\"14\" fill=\"#ebe6ff\" stroke=\"#6d45e0\" stroke-width=\"2\"/><text x=\"450\" y=\"148\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#6d45e0\">Claude Code subagent</text><text x=\"450\" y=\"176\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"400\" fill=\"#17152a\">solid, documented, in-house</text><rect x=\"610\" y=\"10\" width=\"280\" height=\"60\" rx=\"14\" fill=\"#ffe6f3\" stroke=\"#c21c7a\" stroke-width=\"2\"/><text x=\"750\" y=\"46\" text-anchor=\"middle\" font-size=\"15\" font-weight=\"700\" fill=\"#17152a\">Different-lineage critic</text><path d=\"M750 74L750 99\" stroke=\"#5d5a78\" stroke-width=\"3\" fill=\"none\"/><path d=\"M750 108L744 99L756 99z\" fill=\"#5d5a78\"/><rect x=\"610\" y=\"114\" width=\"280\" height=\"92\" rx=\"14\" fill=\"#ffe6f3\" stroke=\"#c21c7a\" stroke-width=\"2\"/><text x=\"750\" y=\"148\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#c21c7a\">Self-built hook</text><text x=\"750\" y=\"176\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"400\" fill=\"#17152a\">in the style of second-opinion</text></svg><svg class=\"fig-narrow\" viewBox=\"0 0 390 388\" role=\"img\" aria-label=\"Which tool closes which review gap: PR-Agent, the Claude Code subagent, or a self-built cross-provider hook\"><rect x=\"10\" y=\"10\" width=\"370\" height=\"34\" rx=\"12\" fill=\"#e0f6f8\" stroke=\"#0e8c99\" stroke-width=\"2\"/><text x=\"195\" y=\"33\" text-anchor=\"middle\" font-size=\"15\" font-weight=\"700\" fill=\"#17152a\">Day-to-day PR review</text><path d=\"M195 47 L195 58\" stroke=\"#5d5a78\" stroke-width=\"3\" fill=\"none\"/><path d=\"M195 66 L189 57 L201 57 z\" fill=\"#5d5a78\"/><rect x=\"10\" y=\"66\" width=\"370\" height=\"54\" rx=\"12\" fill=\"#e0f6f8\" stroke=\"#0e8c99\" stroke-width=\"2\"/><text x=\"195\" y=\"89\" text-anchor=\"middle\" font-size=\"15\" font-weight=\"700\" fill=\"#0e8c99\">PR-Agent</text><text x=\"195\" y=\"109\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"400\" fill=\"#17152a\">mature, self-hostable, provider-agnostic</text><rect x=\"10\" y=\"136\" width=\"370\" height=\"34\" rx=\"12\" fill=\"#ebe6ff\" stroke=\"#6d45e0\" stroke-width=\"2\"/><text x=\"195\" y=\"159\" text-anchor=\"middle\" font-size=\"15\" font-weight=\"700\" fill=\"#17152a\">Fresh-context critic</text><path d=\"M195 173 L195 184\" stroke=\"#5d5a78\" stroke-width=\"3\" fill=\"none\"/><path d=\"M195 192 L189 183 L201 183 z\" fill=\"#5d5a78\"/><rect x=\"10\" y=\"192\" width=\"370\" height=\"54\" rx=\"12\" fill=\"#ebe6ff\" stroke=\"#6d45e0\" stroke-width=\"2\"/><text x=\"195\" y=\"215\" text-anchor=\"middle\" font-size=\"15\" font-weight=\"700\" fill=\"#6d45e0\">Claude Code subagent</text><text x=\"195\" y=\"235\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"400\" fill=\"#17152a\">solid, documented, in-house</text><rect x=\"10\" y=\"262\" width=\"370\" height=\"34\" rx=\"12\" fill=\"#ffe6f3\" stroke=\"#c21c7a\" stroke-width=\"2\"/><text x=\"195\" y=\"285\" text-anchor=\"middle\" font-size=\"15\" font-weight=\"700\" fill=\"#17152a\">Different-lineage critic</text><path d=\"M195 299 L195 310\" stroke=\"#5d5a78\" stroke-width=\"3\" fill=\"none\"/><path d=\"M195 318 L189 309 L201 309 z\" fill=\"#5d5a78\"/><rect x=\"10\" y=\"318\" width=\"370\" height=\"54\" rx=\"12\" fill=\"#ffe6f3\" stroke=\"#c21c7a\" stroke-width=\"2\"/><text x=\"195\" y=\"341\" text-anchor=\"middle\" font-size=\"15\" font-weight=\"700\" fill=\"#c21c7a\">Self-built hook</text><text x=\"195\" y=\"361\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"400\" fill=\"#17152a\">in the style of second-opinion</text></svg><figcaption>The gap between a review button and a fresh, different-lineage critic is mostly DIY.</figcaption></figure>\n\n<h2 id=\"sources\">Sources</h2>\n<ul>\n<li><a href=\"https://github.blog/changelog/2025-09-18-copilot-code-review-now-in-jetbrains-ides-and-visual-studio/\">GitHub Changelog — Copilot code review in JetBrains IDEs and Visual Studio</a></li>\n<li><a href=\"https://github.blog/changelog/2026-02-13-new-features-and-improvements-in-github-copilot-in-jetbrains-ides-2/\">GitHub Changelog — Copilot in JetBrains IDEs, Feb 2026 update</a></li>\n<li><a href=\"https://blog.jetbrains.com/webstorm/2026/07/webstorm-2026-2/\">JetBrains blog — WebStorm 2026.2 release notes</a></li>\n<li><a href=\"https://code.claude.com/docs/en/code-review\">Claude Code Docs — Code Review</a></li>\n<li><a href=\"https://github.com/qodo-ai/pr-agent\">qodo-ai/pr-agent on GitHub</a> — star/fork counts checked directly</li>\n<li><a href=\"https://github.com/pghqdev/second-opinion\">pghqdev/second-opinion on GitHub</a> — fetched directly, repo stats confirmed (0 stars/forks, 6 commits)</li>\n<li>General 2026 coverage of Cursor&#39;s agent/review capabilities (multiple review-aggregator sites — directional, not primary-sourced; weaker than the above)</li>\n</ul>\n";
